<script setup>
import {ref,reactive,onMounted,onBeforeUnmount,watch} from 'vue'
import {session,explicitDemo} from '../utils/sessionState'
import {telemetryApi} from '../api/telemetry'
import {filterForm,runtimeQuery,eventPage,outcomes,reasons,tagType,collectorStatus} from '../utils/telemetry'
import {receivingReadGate} from '../utils/receiving'
import {displayTime} from '../utils/time'
import RuntimeEventDetails from './RuntimeEventDetails.vue'
const props=defineProps({capabilityId:{type:String,default:''}})
const form=reactive({...filterForm(),collectionPoint:'KAFKA_PRODUCER',scopeType:'capabilityId'}),rows=ref([]),total=ref(0),page=ref(1),size=ref(20),error=ref(''),loading=ref(false),auto=ref(false),collector=ref(null),collectorError=ref('')
form.scopeId=props.capabilityId
const gate=receivingReadGate(),collectorGate=receivingReadGate();let applied=runtimeQuery(form),timer
async function load(background=false){
  if(explicitDemo||!session.user||background&&(loading.value||document.hidden))return
  const token=gate.next(),epoch=session.epoch,params={...applied,limit:size.value,offset:(page.value-1)*size.value};loading.value=true;error.value='';if(!background){rows.value=[];total.value=0}
  try{const data=eventPage(await telemetryApi.events(params),params);if(gate.current(token)&&epoch===session.epoch){rows.value=data.rows;total.value=data.total}}
  catch(e){if(gate.current(token)&&epoch===session.epoch){rows.value=[];total.value=0;auto.value=false;error.value=e.response?.data?.message||e.message||'发送日志读取失败'}}finally{if(gate.current(token)&&epoch===session.epoch)loading.value=false}
}
function query(){try{applied=runtimeQuery(form);page.value=1;load()}catch(e){gate.invalidate();rows.value=[];total.value=0;loading.value=false;error.value=e.message}}
watch(()=>[props.capabilityId,session.epoch],()=>{gate.invalidate();collectorGate.invalidate();rows.value=[];total.value=0;collector.value=null;collectorError.value='';error.value='';loading.value=false;page.value=1;form.scopeType='capabilityId';form.scopeId=props.capabilityId;applied=runtimeQuery(form);if(session.user&&!explicitDemo)load()})
async function collectorLoad(){if(explicitDemo||session.user?.role!=='ADMIN')return;const token=collectorGate.next();collector.value=null;collectorError.value='';try{const data=collectorStatus(await telemetryApi.collector());if(collectorGate.current(token))collector.value=data}catch{if(collectorGate.current(token))collectorError.value='采集状态读取失败，日志完整性无法确认'}}
watch(auto,value=>{clearInterval(timer);if(value&&!explicitDemo)timer=setInterval(()=>load(true),5000)})
onMounted(()=>{load();collectorLoad()});onBeforeUnmount(()=>{gate.dispose();collectorGate.dispose();clearInterval(timer);rows.value=[];collector.value=null})
</script>
<template><section class="stack" data-testid="production-logs">
  <div class="toolbar"><el-tag v-if="props.capabilityId">当前接口能力</el-tag><template v-else><el-select v-model="form.scopeType" style="width:130px" aria-label="发送日志对象"><el-option label="接口能力" value="capabilityId" /><el-option label="数据资源" value="resourceId" /></el-select><el-input v-model="form.scopeId" placeholder="完整编号（可选）" aria-label="发送关联编号" clearable style="width:330px" /></template><el-select v-model="form.outcome" placeholder="全部结果" aria-label="发送结果" clearable style="width:130px"><el-option v-for="(label,key) in outcomes" :key="key" :value="key" :label="label" /></el-select><el-date-picker v-model="form.range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" style="max-width:360px" /><el-button type="primary" :disabled="explicitDemo" @click="query">查询发送日志</el-button><el-button :disabled="explicitDemo" :loading="loading" @click="load()">刷新</el-button><el-switch v-model="auto" :disabled="explicitDemo" active-text="每5秒刷新" /></div>
  <el-alert v-if="explicitDemo" title="演示模式不读取真实发送日志" type="warning" :closable="false" />
  <el-alert title="历史记录由服务端保存，刷新页面后仍可查询。上报可能有延迟；Kafka回执不代表需求方已落库。" type="info" :closable="false" />
  <el-alert v-if="error" :title="error" type="error" :closable="false" data-testid="production-log-error"><el-button link @click="load()">重试</el-button></el-alert>
  <template v-else><el-table :data="rows" v-loading="loading" row-key="event_id" empty-text="暂无已上报的发送日志" data-testid="production-log-table"><el-table-column type="expand"><template #default="{row}"><div class="details"><RuntimeEventDetails :event="row" /></div></template></el-table-column><el-table-column label="发送完成时间" min-width="180"><template #default="{row}">{{displayTime(row.completed_at)}}</template></el-table-column><el-table-column label="结果" width="90"><template #default="{row}"><el-tag :type="tagType(row.outcome)">{{outcomes[row.outcome]}}</el-tag></template></el-table-column><el-table-column label="处理说明" min-width="170"><template #default="{row}">{{reasons[row.reason_code]}}</template></el-table-column><el-table-column prop="topic" label="消息主题" min-width="220" show-overflow-tooltip /><el-table-column label="分区" width="75"><template #default="{row}">{{row.topic_partition??'—'}}</template></el-table-column><el-table-column label="消息位置" width="100"><template #default="{row}">{{row.topic_offset??'—'}}</template></el-table-column><el-table-column prop="byte_count" label="载荷字节" width="110" /><el-table-column prop="duration_ms" label="耗时（毫秒）" width="125" /><el-table-column prop="capability_id" label="能力编号" min-width="190" show-overflow-tooltip /></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total,sizes,prev,pager,next" :disabled="loading||explicitDemo" @change="load()" /></template>
  <template v-if="session.user?.role==='ADMIN'"><div><el-button link :disabled="explicitDemo" @click="collectorLoad">刷新日志采集状态</el-button></div><el-alert v-if="collectorError" :title="collectorError" type="warning" :closable="false" /><el-descriptions v-if="collector" :column="3" border><el-descriptions-item label="自动采集">{{collector.enabled?'已开启':'已关闭'}}</el-descriptions-item><el-descriptions-item label="待补报报告">{{collector.pending_reports}}</el-descriptions-item><el-descriptions-item label="最近上报">{{displayTime(collector.last_success_at)}}</el-descriptions-item><el-descriptions-item label="丢弃事件">{{collector.dropped_events}}</el-descriptions-item><el-descriptions-item label="隔离报告">{{collector.quarantined_reports}}</el-descriptions-item><el-descriptions-item label="存储失败">{{collector.spool_failures}}</el-descriptions-item></el-descriptions><el-alert v-if="collector&&(collector.dropped_events||collector.quarantined_reports||collector.spool_failures||!collector.enabled)" title="采集存在缺口，不能据此宣称完整传输记录" type="warning" :closable="false" /></template>
</section></template>
<style scoped>.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.details{padding:18px 28px;max-width:1000px}.el-pagination{justify-content:flex-end}</style>
